/**
 * Crow performances, authored as anatomical poses rather than shape morphs.
 * All poses are complete snapshots: scrubbing and reversing are deterministic.
 * Rotation is in degrees, translation in the SVG's 800-unit stage coordinates.
 *
 * Acting references (read while rebuilding):
 * https://schoolofmotion.com/blog/how-to-animate-character-takes
 * https://www.animationmentor.com/blog/tutorial-animate-blinks-eye-movement/
 * https://www.animationmentor.com/blog/exaggeration-the-12-basic-principles-of-animation/
 * Start / anticipation / accent / settle; eye focus before head and body;
 * quick, asymmetric lid closure and readable holds. Exaggerate joint poses,
 * silhouette and timing. Body volumes remain rigid; eye acting is independent.
 */
import { resolvePose } from './pose.js';
import { eyePerformance } from './eye-performances.js';

export const categories = [
  'All motions', 'Character', 'On the move', 'Reactions',
  'Celebrations', 'Helpful gestures', 'Mumbai life', 'Quiet moments',
];
const ink = { mint:'#c6ddc9', blue:'#c7dce9', lilac:'#d4cce5', peach:'#edcbbb', yellow:'#f1dfa4', rose:'#ecc8d0' };
const F = (at, pose={}, ease='smooth') => ({at,pose,ease});
const B = (at,label) => ({at,label});
function performance(spec) {
  const effectPosition={effectX:spec.effectOffset?.[0]??0,effectY:spec.effectOffset?.[1]??0};
  const eyes=eyePerformance(spec.id,spec.duration);
  return {
    effect:'none', loop:false, ...spec,
    eyes,
    hero:resolvePose({...effectPosition,effect:spec.effect && spec.effect!=='none'?1:0,...spec.hero,...eyes.hero}),
    frames:spec.frames.map(f=>({...f,pose:resolvePose({...effectPosition,...f.pose})})),
  };
}

/**
 * Alternating contacts are authored in WORLD space. A planted foot's local
 * offset cancels the moving root exactly, including between keyframes.
 * Only the swing foot travels. These are translated one-shot walks, not a
 * floating in-place cycle. Run includes a short, explicit aerial phase.
 */
function contacts({kind, steps=4, distance=160, start=.16, end=.8}) {
  const frames=[], initial=-distance/2, stride=distance/steps;
  const world={L:380+initial+35,R:480+initial-35};
  const rest={L:380,R:480};
  const styles={
    strut:{height:65,body:-7,head:-7,wing:13,fold:14},
    run:{height:83,body:21,head:-17,wing:30,fold:-22},
    sneak:{height:47,body:15,head:-10,wing:18,fold:28},
  };
  const s=styles[kind];
  for(let step=0;step<steps;step++) {
    const moving=step%2===0?'L':'R', planted=moving==='L'?'R':'L';
    const from=world[moving], to=from+2*stride;
    for(const q of [0,.22,.5,.78,1]) {
      if(step>0&&q===0)continue;
      const x=initial+(step+q)*stride;
      const index=[0,.22,.5,.78,1].indexOf(q);
      const swingH=[0,-s.height*.4,-s.height,-s.height*.48,0][index];
      const airborne=kind==='run'&&q===.5;
      const y=airborne?-16:0;
      const pose={x,y,body:s.body,head:s.head+(q===.5?-5:0),headY:q===.5?-4:0,
        crouch:kind==='sneak'?.64:(q===0||q===1?.2:0),
        wing:s.wing+(moving==='L'?10:-5),wingFold:s.fold,
        farWing:s.wing+(moving==='R'?17:-6),farWingFold:-s.fold,
        tail:kind==='strut'?(moving==='L'?8:14):(moving==='L'?-10:7),gazeX:10,gazeY:kind==='sneak'?4:0,
        lidTop:kind==='sneak'?.23:kind==='strut'?.13:0,
        pupil:kind==='run'?.82:1,
      };
      pose[`foot${moving}X`]=from+(to-from)*q-x-rest[moving];
      pose[`foot${moving}Y`]=swingH-y;
      pose[`foot${moving}A`]=q===.5?-25:q===.78?18:0;
      pose[`foot${planted}X`]=world[planted]-x-rest[planted];
      pose[`foot${planted}Y`]=(airborne?-32:0)-y;
      pose[`foot${planted}A`]=airborne?22:0;
      frames.push(F(start+(end-start)*(step+q)/steps,pose,'linear'));
    }
    world[moving]=to;
  }
  return frames;
}

